94	class MarkPointView extends MarkerView {
95	
96	    static type = 'markPoint';
97	    type = MarkPointView.type;
98	
99	    markerGroupMap: HashMap<SymbolDraw>;
100	
101	    updateTransform(markPointModel: MarkPointModel, ecModel: GlobalModel, api: ExtensionAPI) {
102	        ecModel.eachSeries(function (seriesModel) {
103	            const mpModel = MarkerModel.getMarkerModelFromSeries(seriesModel, 'markPoint') as MarkPointModel;
104	            if (mpModel) {
105	                updateMarkerLayout(
106	                    mpModel.getData(),
107	                    seriesModel, api
108	                );
109	                this.markerGroupMap.get(seriesModel.id).updateLayout();
110	            }
111	        }, this);
112	    }
113	
114	    renderSeries(
115	        seriesModel: SeriesModel,
116	        mpModel: MarkPointModel,
117	        ecModel: GlobalModel,
118	        api: ExtensionAPI
119	    ) {
120	        const coordSys = seriesModel.coordinateSystem;
121	        const seriesId = seriesModel.id;
122	        const seriesData = seriesModel.getData();
123	
124	        const symbolDrawMap = this.markerGroupMap;
125	        const symbolDraw = symbolDrawMap.get(seriesId)
126	            || symbolDrawMap.set(seriesId, new SymbolDraw());
127	
128	        const mpData = createData(coordSys, seriesModel, mpModel);
129	
130	        // FIXME
131	        mpModel.setData(mpData);
132	
133	        updateMarkerLayout(mpModel.getData(), seriesModel, api);
134	
135	        mpData.each(function (idx) {
136	            const itemModel = mpData.getItemModel<MarkPointDataItemOption>(idx);
137	            let symbol = itemModel.getShallow('symbol');
138	            let symbolSize = itemModel.getShallow('symbolSize');
139	            let symbolRotate = itemModel.getShallow('symbolRotate');
140	            let symbolOffset = itemModel.getShallow('symbolOffset');
141	            const symbolKeepAspect = itemModel.getShallow('symbolKeepAspect');
142	
143	            // TODO: refactor needed: single data item should not support callback function
144	            if (isFunction(symbol) || isFunction(symbolSize) || isFunction(symbolRotate) || isFunction(symbolOffset)) {
145	                const rawIdx = mpModel.getRawValue(idx);
146	                const dataParams = mpModel.getDataParams(idx);
147	                if (isFunction(symbol)) {
148	                    symbol = symbol(rawIdx, dataParams);
149	                }
150	                if (isFunction(symbolSize)) {
151	                    // FIXME 这里不兼容 ECharts 2.x，2.x 貌似参数是整个数据？
152	                    symbolSize = symbolSize(rawIdx, dataParams);
153	                }
154	                if (isFunction(symbolRotate)) {
155	                    symbolRotate = symbolRotate(rawIdx, dataParams);
156	                }
157	                if (isFunction(symbolOffset)) {
158	                    symbolOffset = symbolOffset(rawIdx, dataParams);
159	                }
160	            }
161	
162	            const style = itemModel.getModel('itemStyle').getItemStyle();
163	            const z2 = itemModel.get('z2');
164	            const color = getVisualFromData(seriesData, 'color') as ZRColor;
165	            if (!style.fill) {
166	                style.fill = color;
167	            }
168	
169	            mpData.setItemVisual(idx, {
170	                z2: retrieve2(z2, 0),
171	                symbol: symbol,
172	                symbolSize: symbolSize,
173	                symbolRotate: symbolRotate,
174	                symbolOffset: symbolOffset,
175	                symbolKeepAspect: symbolKeepAspect,
176	                style
177	            });
178	        });
179	
180	        // TODO Text are wrong
181	        symbolDraw.updateData(mpData);
182	        this.group.add(symbolDraw.group);
183	
184	        // Set host model for tooltip
185	        // FIXME
186	        mpData.eachItemGraphicEl(function (el) {
187	            el.traverse(function (child) {
188	                getECData(child).dataModel = mpModel;
189	            });
190	        });
191	
192	        this.markKeep(symbolDraw);
193	
194	        symbolDraw.group.silent = mpModel.get('silent') || seriesModel.get('silent');
195	    }
196	}
197	
198	function createData(
199	    coordSys: CoordinateSystem,
200	    seriesModel: SeriesModel,
201	    mpModel: MarkPointModel
202	) {
203	    let coordDimsInfos: SeriesDimensionDefine[];
204	    if (coordSys) {
205	        coordDimsInfos = map(coordSys && coordSys.dimensions, function (coordDim) {
206	            const info = seriesModel.getData().getDimensionInfo(
207	                seriesModel.getData().mapDimension(coordDim)
208	            ) || {};
209	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
210	            return extend(extend({}, info), {
211	                name: coordDim,
212	                // DON'T use ordinalMeta to parse and collect ordinal.
213	                ordinalMeta: null
214	            });
215	        });
216	    }
217	    else {
218	        coordDimsInfos = [{
219	            name: 'value',
220	            type: 'float'
221	        }];
222	    }
223	
224	    const mpData = new SeriesData(coordDimsInfos, mpModel);
225	    let dataOpt = map(mpModel.get('data'), curry(
226	            markerHelper.dataTransform, seriesModel
227	        ));
228	    if (coordSys) {
229	        dataOpt = filter(
230	            dataOpt, curry(markerHelper.dataFilter, coordSys)
231	        );
232	    }
233	
234	    const dimValueGetter = markerHelper.createMarkerDimValueGetter(!!coordSys, coordDimsInfos);
235	    mpData.initData(dataOpt, null, dimValueGetter);
236	
237	    return mpData;
238	}
239	
240	export default MarkPointView;
