65	    seriesModel: SeriesModel,
66	    coordSys: CoordinateSystem,
67	    maModel: MarkAreaModel,
68	    item: MarkArea2DDataItemOption
69	): MarkAreaMergedItemOption {
70	    // item may be null
71	    const item0 = item[0];
72	    const item1 = item[1];
73	    if (!item0 || !item1) {
74	        return;
75	    }
76	
77	    const lt = markerHelper.dataTransform(seriesModel, item0);
78	    const rb = markerHelper.dataTransform(seriesModel, item1);
79	
80	    // FIXME make sure lt is less than rb
81	    const ltCoord = lt.coord;
82	    const rbCoord = rb.coord;
83	    ltCoord[0] = retrieve(ltCoord[0], -Infinity);
84	    ltCoord[1] = retrieve(ltCoord[1], -Infinity);
85	
86	    rbCoord[0] = retrieve(rbCoord[0], Infinity);
87	    rbCoord[1] = retrieve(rbCoord[1], Infinity);
88	
89	    // Merge option into one
90	    const result: MarkAreaMergedItemOption = mergeAll([{}, lt, rb]);
91	
92	    result.coord = [
93	        lt.coord, rb.coord
94	    ];
95	    result.x0 = lt.x;
96	    result.y0 = lt.y;
97	    result.x1 = rb.x;
98	    result.y1 = rb.y;
99	    return result;
100	};
101	
102	function isInfinity(val: ScaleDataValue) {
103	    return !isNaN(val as number) && !isFinite(val as number);
104	}
105	
106	// If a markArea has one dim
107	function ifMarkAreaHasOnlyDim(
108	    dimIndex: number,
109	    fromCoord: ScaleDataValue[],
110	    toCoord: ScaleDataValue[],
111	    coordSys: CoordinateSystem
112	) {
113	    const otherDimIndex = 1 - dimIndex;
114	    return isInfinity(fromCoord[otherDimIndex]) && isInfinity(toCoord[otherDimIndex]);
115	}
116	
117	function markAreaFilter(coordSys: CoordinateSystem, item: MarkAreaMergedItemOption) {
118	    const fromCoord = item.coord[0];
119	    const toCoord = item.coord[1];
120	    const item0 = {
121	        coord: fromCoord,
122	        x: item.x0,
123	        y: item.y0
124	    };
125	    const item1 = {
126	        coord: toCoord,
127	        x: item.x1,
128	        y: item.y1
129	    };
130	    if (isCoordinateSystemType<Cartesian2D>(coordSys, 'cartesian2d')) {
131	        // In case
132	        // {
133	        //  markArea: {
134	        //    data: [{ yAxis: 2 }]
135	        //  }
136	        // }
137	        if (
138	            fromCoord && toCoord
139	            && (ifMarkAreaHasOnlyDim(1, fromCoord, toCoord, coordSys)
140	            || ifMarkAreaHasOnlyDim(0, fromCoord, toCoord, coordSys))
141	        ) {
142	            return true;
143	        }
144	        // Directly returning true may also do the work,
145	        // because markArea will not be shown automatically
146	        // when it's not included in coordinate system.
147	        // But filtering ahead can avoid keeping rendering markArea
148	        // when there are too many of them.
149	        return markerHelper.zoneFilter(coordSys, item0, item1);
150	    }
151	    return markerHelper.dataFilter(coordSys, item0)
152	        || markerHelper.dataFilter(coordSys, item1);
153	}
