234	class MarkAreaView extends MarkerView {
235	
236	    static type = 'markArea';
237	    type = MarkAreaView.type;
238	
239	    markerGroupMap: HashMap<MarkAreaDrawGroup>;
240	
241	    updateTransform(markAreaModel: MarkAreaModel, ecModel: GlobalModel, api: ExtensionAPI) {
242	        ecModel.eachSeries(function (seriesModel) {
243	            const maModel = MarkerModel.getMarkerModelFromSeries(seriesModel, 'markArea') as MarkAreaModel;
244	            if (maModel) {
245	                const areaData = maModel.getData();
246	                areaData.each(function (idx) {
247	                    const points = map(dimPermutations, function (dim) {
248	                        return getSingleMarkerEndPoint(areaData, idx, dim, seriesModel, api);
249	                    });
250	                    // Layout
251	                    areaData.setItemLayout(idx, points);
252	                    const el = areaData.getItemGraphicEl(idx) as graphic.Polygon;
253	                    el.setShape('points', points);
254	                });
255	            }
256	        }, this);
257	    }
258	
259	    renderSeries(
260	        seriesModel: SeriesModel,
261	        maModel: MarkAreaModel,
262	        ecModel: GlobalModel,
263	        api: ExtensionAPI
264	    ) {
265	        const coordSys = seriesModel.coordinateSystem;
266	        const seriesId = seriesModel.id;
267	        const seriesData = seriesModel.getData();
268	
269	        const areaGroupMap = this.markerGroupMap;
270	        const polygonGroup = areaGroupMap.get(seriesId)
271	            || areaGroupMap.set(seriesId, {group: new graphic.Group()});
272	
273	        this.group.add(polygonGroup.group);
274	        this.markKeep(polygonGroup);
275	
276	        const areaData = createList(coordSys, seriesModel, maModel);
277	
278	        // Line data for tooltip and formatter
279	        maModel.setData(areaData);
280	
281	        // Update visual and layout of line
282	        areaData.each(function (idx) {
283	            // Layout
284	            const points = map(dimPermutations, function (dim) {
285	                return getSingleMarkerEndPoint(areaData, idx, dim, seriesModel, api);
286	            });
287	            const xAxisScale = coordSys.getAxis('x').scale;
288	            const yAxisScale = coordSys.getAxis('y').scale;
289	            const xAxisExtent = xAxisScale.getExtent();
290	            const yAxisExtent = yAxisScale.getExtent();
291	            const xPointExtent = [xAxisScale.parse(areaData.get('x0', idx)), xAxisScale.parse(areaData.get('x1', idx))];
292	            const yPointExtent = [yAxisScale.parse(areaData.get('y0', idx)), yAxisScale.parse(areaData.get('y1', idx))];
293	            numberUtil.asc(xPointExtent);
294	            numberUtil.asc(yPointExtent);
295	            const overlapped = !(xAxisExtent[0] > xPointExtent[1] || xAxisExtent[1] < xPointExtent[0]
296	                                || yAxisExtent[0] > yPointExtent[1] || yAxisExtent[1] < yPointExtent[0]);
297	            // If none of the area is inside coordSys, allClipped is set to be true
298	            // in layout so that label will not be displayed. See #12591
299	            const allClipped = !overlapped;
300	            areaData.setItemLayout(idx, {
301	                points: points,
302	                allClipped: allClipped
303	            });
304	
305	            const itemModel = areaData.getItemModel<MarkAreaMergedItemOption>(idx);
306	            const style = itemModel.getModel('itemStyle').getItemStyle();
307	            const z2 = itemModel.get('z2');
308	            const color = getVisualFromData(seriesData, 'color') as ZRColor;
309	            if (!style.fill) {
310	                style.fill = color;
311	                if (isString(style.fill)) {
312	                    style.fill = colorUtil.modifyAlpha(style.fill, 0.4);
313	                }
314	            }
315	            if (!style.stroke) {
316	                style.stroke = color;
317	            }
318	            // Visual
319	            areaData.setItemVisual(idx, 'style', style);
320	            areaData.setItemVisual(idx, 'z2', retrieve2(z2, 0));
321	        });
322	
323	
324	        areaData.diff(inner(polygonGroup).data)
325	            .add(function (idx) {
326	                const layout = areaData.getItemLayout(idx);
327	                const z2 = areaData.getItemVisual(idx, 'z2');
328	                if (!layout.allClipped) {
329	                    const polygon = new graphic.Polygon({
330	                        z2: retrieve2(z2, 0),
331	                        shape: {
332	                            points: layout.points
333	                        }
334	                    });
335	                    areaData.setItemGraphicEl(idx, polygon);
336	                    polygonGroup.group.add(polygon);
337	                }
338	            })
339	            .update(function (newIdx, oldIdx) {
340	                let polygon = inner(polygonGroup).data.getItemGraphicEl(oldIdx) as graphic.Polygon;
341	                const layout = areaData.getItemLayout(newIdx);
342	                const z2 = areaData.getItemVisual(newIdx, 'z2');
343	                if (!layout.allClipped) {
344	                    if (polygon) {
345	                        graphic.updateProps(polygon, {
346	                            z2: retrieve2(z2, 0),
347	                            shape: {
348	                                points: layout.points
349	                            }
350	                        }, maModel, newIdx);
351	                    }
352	                    else {
353	                        polygon = new graphic.Polygon({
354	                            shape: {
355	                                points: layout.points
356	                            }
357	                        });
358	                    }
359	                    areaData.setItemGraphicEl(newIdx, polygon);
360	                    polygonGroup.group.add(polygon);
361	                }
362	                else if (polygon) {
363	                    polygonGroup.group.remove(polygon);
364	                }
365	            })
366	            .remove(function (idx) {
367	                const polygon = inner(polygonGroup).data.getItemGraphicEl(idx);
368	                polygonGroup.group.remove(polygon);
369	            })
370	            .execute();
371	
372	        areaData.eachItemGraphicEl(function (polygon: graphic.Polygon, idx) {
373	            const itemModel = areaData.getItemModel<MarkAreaMergedItemOption>(idx);
374	            const style = areaData.getItemVisual(idx, 'style');
375	            polygon.useStyle(areaData.getItemVisual(idx, 'style'));
376	
377	            setLabelStyle(
378	                polygon, getLabelStatesModels(itemModel),
379	                {
380	                    labelFetcher: maModel,
381	                    labelDataIndex: idx,
382	                    defaultText: areaData.getName(idx) || '',
383	                    inheritColor: isString(style.fill)
384	                        ? colorUtil.modifyAlpha(style.fill, 1) : tokens.color.neutral99
385	                }
386	            );
387	
388	            setStatesStylesFromModel(polygon, itemModel);
389	
390	            toggleHoverEmphasis(polygon, null, null, itemModel.get(['emphasis', 'disabled']));
391	
392	            getECData(polygon).dataModel = maModel;
393	        });
394	
395	        inner(polygonGroup).data = areaData;
396	
397	        polygonGroup.group.silent = maModel.get('silent') || seriesModel.get('silent');
398	    }
399	}
