401	function createList(
402	    coordSys: CoordinateSystem,
403	    seriesModel: SeriesModel,
404	    maModel: MarkAreaModel
405	) {
406	
407	    let areaData: SeriesData<MarkAreaModel>;
408	    let dataDims: SeriesDimensionDefine[];
409	    const dims = ['x0', 'y0', 'x1', 'y1'];
410	    if (coordSys) {
411	        const coordDimsInfos: SeriesDimensionDefine[] = map(coordSys && coordSys.dimensions, function (coordDim) {
412	            const data = seriesModel.getData();
413	            const info = data.getDimensionInfo(
414	                data.mapDimension(coordDim)
415	            ) || {};
416	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
417	            return extend(extend({}, info), {
418	                name: coordDim,
419	                // DON'T use ordinalMeta to parse and collect ordinal.
420	                ordinalMeta: null
421	            });
422	        });
423	        dataDims = map(dims, (dim, idx) => ({
424	            name: dim,
425	            type: coordDimsInfos[idx % 2].type
426	        }));
427	        areaData = new SeriesData(dataDims, maModel);
428	    }
429	    else {
430	        dataDims = [{
431	            name: 'value',
432	            type: 'float'
433	        }];
434	        areaData = new SeriesData(dataDims, maModel);
435	    }
436	
437	    let optData = map(maModel.get('data'), curry(
438	        markAreaTransform, seriesModel, coordSys, maModel
439	    ));
440	    if (coordSys) {
441	        optData = filter(
442	            optData, curry(markAreaFilter, coordSys)
443	        );
444	    }
445	
446	    const dimValueGetter: markerHelper.MarkerDimValueGetter<MarkAreaMergedItemOption> = coordSys
447	        ? function (item, dimName, dataIndex, dimIndex) {
448	            // TODO should convert to ParsedValue?
449	            const rawVal = item.coord[Math.floor(dimIndex / 2)][dimIndex % 2];
450	            return parseDataValue(rawVal, dataDims[dimIndex]);
451	        }
452	        : function (item, dimName, dataIndex, dimIndex) {
453	            return parseDataValue(item.value, dataDims[dimIndex]);
454	        };
455	    areaData.initData(optData, null, dimValueGetter);
456	    areaData.hasItemOption = true;
457	    return areaData;
458	}
