55	// Item option for configuring line and each end of symbol.
56	// Line option. be merged from configuration of two ends.
57	type MarkLineMergedItemOption = MarkLine2DDataItemOption[number];
58	
59	const inner = makeInner<{
60	    // from data
61	    from: SeriesData<MarkLineModel>
62	    // to data
63	    to: SeriesData<MarkLineModel>
64	}, MarkLineModel>();
65	
66	const markLineTransform = function (
67	    seriesModel: SeriesModel,
68	    coordSys: CoordinateSystem,
69	    mlModel: MarkLineModel,
70	    item: MarkLineOption['data'][number]
71	) {
72	    const data = seriesModel.getData();
73	
74	    let itemArray: MarkLineMergedItemOption[];
75	    if (!isArray(item)) {
76	        // Special type markLine like 'min', 'max', 'average', 'median'
77	        const mlType = item.type;
78	        if (
79	            mlType === 'min' || mlType === 'max' || mlType === 'average' || mlType === 'median'
80	            // In case
81	            // data: [{
82	            //   yAxis: 10
83	            // }]
84	            || (item.xAxis != null || item.yAxis != null)
85	        ) {
86	
87	            let valueAxis;
88	            let value;
89	
90	            if (item.yAxis != null || item.xAxis != null) {
91	                valueAxis = coordSys.getAxis(item.yAxis != null ? 'y' : 'x');
92	                value = retrieve(item.yAxis, item.xAxis);
93	            }
94	            else {
95	                const axisInfo = markerHelper.getAxisInfo(item, data, coordSys, seriesModel);
96	                valueAxis = axisInfo.valueAxis;
97	                const valueDataDim = getStackedDimension(data, axisInfo.valueDataDim);
98	                value = markerHelper.numCalculate(data, valueDataDim, mlType);
99	            }
100	            const valueIndex = valueAxis.dim === 'x' ? 0 : 1;
101	            const baseIndex = 1 - valueIndex;
102	
103	            // Normized to 2d data with start and end point
104	            const mlFrom = clone(item) as MarkLine2DDataItemOption[number];
105	            const mlTo = {
106	                coord: []
107	            } as MarkLine2DDataItemOption[number];
108	
109	            mlFrom.type = null;
110	
111	            mlFrom.coord = [];
112	            mlFrom.coord[baseIndex] = -Infinity;
113	            mlTo.coord[baseIndex] = Infinity;
114	
115	            const precision = mlModel.get('precision');
116	            if (precision >= 0 && isNumber(value)) {
117	                value = +value.toFixed(Math.min(precision, 20));
118	            }
119	
120	            mlFrom.coord[valueIndex] = mlTo.coord[valueIndex] = value;
121	
122	            itemArray = [mlFrom, mlTo, { // Extra option for tooltip and label
123	                type: mlType,
124	                valueIndex: item.valueIndex,
125	                // Force to use the value of calculated value.
126	                value: value
127	            }];
128	        }
129	        else {
130	            // Invalid data
131	            if (__DEV__) {
132	                logError('Invalid markLine data.');
133	            }
134	            itemArray = [];
135	        }
136	    }
137	    else {
138	        itemArray = item;
139	    }
140	
141	    const normalizedItem = [
142	        markerHelper.dataTransform(seriesModel, itemArray[0]),
143	        markerHelper.dataTransform(seriesModel, itemArray[1]),
144	        extend({}, itemArray[2])
145	    ];
146	
147	    // Avoid line data type is extended by from(to) data type
148	    normalizedItem[2].type = normalizedItem[2].type || null;
149	
150	    // Merge from option and to option into line option
151	    merge(normalizedItem[2], normalizedItem[0]);
152	    merge(normalizedItem[2], normalizedItem[1]);
153	
154	    return normalizedItem;
155	};
156	
157	function isInfinity(val: ScaleDataValue) {
158	    return !isNaN(val as number) && !isFinite(val as number);
159	}
