161	// If a markLine has one dim
162	function ifMarkLineHasOnlyDim(
163	    dimIndex: number,
164	    fromCoord: ScaleDataValue[],
165	    toCoord: ScaleDataValue[],
166	    coordSys: CoordinateSystem
167	) {
168	    const otherDimIndex = 1 - dimIndex;
169	    const dimName = coordSys.dimensions[dimIndex];
170	    return isInfinity(fromCoord[otherDimIndex]) && isInfinity(toCoord[otherDimIndex])
171	        && fromCoord[dimIndex] === toCoord[dimIndex] && coordSys.getAxis(dimName).containData(fromCoord[dimIndex]);
172	}
173	
174	function markLineFilter(
175	    coordSys: CoordinateSystem,
176	    item: MarkLine2DDataItemOption
177	) {
178	    if (coordSys.type === 'cartesian2d') {
179	        const fromCoord = item[0].coord;
180	        const toCoord = item[1].coord;
181	        // In case
182	        // {
183	        //  markLine: {
184	        //    data: [{ yAxis: 2 }]
185	        //  }
186	        // }
187	        if (
188	            fromCoord && toCoord
189	            && (ifMarkLineHasOnlyDim(1, fromCoord, toCoord, coordSys)
190	            || ifMarkLineHasOnlyDim(0, fromCoord, toCoord, coordSys))
191	        ) {
192	            return true;
193	        }
194	    }
195	    return markerHelper.dataFilter(coordSys, item[0])
196	        && markerHelper.dataFilter(coordSys, item[1]);
197	}
