441	function createList(coordSys: CoordinateSystem, seriesModel: SeriesModel, mlModel: MarkLineModel) {
442	
443	    let coordDimsInfos: SeriesDimensionDefine[];
444	    if (coordSys) {
445	        coordDimsInfos = map(coordSys && coordSys.dimensions, function (coordDim) {
446	            const info = seriesModel.getData().getDimensionInfo(
447	                seriesModel.getData().mapDimension(coordDim)
448	            ) || {};
449	            // In map series data don't have lng and lat dimension. Fallback to same with coordSys
450	            return extend(extend({}, info), {
451	                name: coordDim,
452	                // DON'T use ordinalMeta to parse and collect ordinal.
453	                ordinalMeta: null
454	            });
455	        });
456	    }
457	    else {
458	        coordDimsInfos = [{
459	            name: 'value',
460	            type: 'float'
461	        }];
462	    }
463	
464	    const fromData = new SeriesData(coordDimsInfos, mlModel);
465	    const toData = new SeriesData(coordDimsInfos, mlModel);
466	    // No dimensions
467	    const lineData = new SeriesData([], mlModel);
468	
469	    let optData = map(mlModel.get('data'), curry(
470	        markLineTransform, seriesModel, coordSys, mlModel
471	    ));
472	    if (coordSys) {
473	        optData = filter(
474	            optData, curry(markLineFilter, coordSys)
475	        );
476	    }
477	
478	    const dimValueGetter = markerHelper.createMarkerDimValueGetter(!!coordSys, coordDimsInfos);
479	
480	    fromData.initData(
481	        map(optData, function (item) {
482	            return item[0];
483	        }),
484	        null,
485	        dimValueGetter
486	    );
487	    toData.initData(
488	        map(optData, function (item) {
489	            return item[1];
490	        }),
491	        null,
492	        dimValueGetter
493	    );
494	    lineData.initData(
495	        map(optData, function (item) {
496	            return item[2];
497	        })
498	    );
499	    lineData.hasItemOption = true;
500	
501	    return {
502	        from: fromData,
503	        to: toData,
504	        line: lineData
505	    };
