758	export function calcZ2Range(el: Element): {
759	    min: number
760	    max: number
761	} {
762	    let max = -Infinity;
763	    let min = Infinity;
764	    traverseElement(el, el => {
765	        visitEl(el);
766	        visitEl(el.getTextContent());
767	        visitEl(el.getTextGuideLine());
768	    });
769	    function visitEl(el: Element): void {
770	        if (!el || el.isGroup) {
771	            return;
772	        }
773	        const currentStates = el.currentStates;
774	        if (currentStates.length) {
775	            for (let idx = 0; idx < currentStates.length; idx++) {
776	                calcZ2(el.states[currentStates[idx]] as Displayable);
777	            }
778	        }
779	        calcZ2(el as Displayable);
780	    }
781	    function calcZ2(entity: Pick<Displayable, 'z2'>): void {
782	        if (entity) {
783	            const z2 = entity.z2;
784	            // Consider z2 may be NullUndefined
785	            if (z2 > max) {
786	                max = z2;
787	            }
788	            if (z2 < min) {
789	                min = z2;
790	            }
791	        }
792	    }
793	    if (min > max) {
794	        min = max = 0;
795	    }
796	    return {min, max};
797	}
