807	function doUpdateZ(
808	    el: Element,
809	    z: number,
810	    zlevel: number,
811	    // FIXME: ideally all the labels shold be above all the glyphs by default,
812	    //  e.g. in graph, edge labels should be above node elements.
813	    //  currenly impl does not garaentee that.
814	    maxZ2: number,
815	): number {
816	    // `ignoreModelZ` is used to intentionally lift elements to cover other elements,
817	    // where maxZ2 (for label.z2) should also not be counted for its parents.
818	    if ((el as ExtendedElement).ignoreModelZ) {
819	        return maxZ2;
820	    }
821	
822	    // Group may also have textContent
823	    const label = el.getTextContent();
824	    const labelLine = el.getTextGuideLine();
825	    const isGroup = el.isGroup;
826	
827	    if (isGroup) {
828	        // set z & zlevel of children elements of Group
829	        const children = (el as Group).childrenRef();
830	        for (let i = 0; i < children.length; i++) {
831	            maxZ2 = mathMax(
832	                doUpdateZ(
833	                    children[i],
834	                    z,
835	                    zlevel,
836	                    maxZ2
837	                ),
838	                maxZ2
839	            );
840	        }
841	    }
842	    else {
843	        // not Group
844	        (el as Displayable).z = z;
845	        (el as Displayable).zlevel = zlevel;
846	
847	        maxZ2 = mathMax((el as Displayable).z2 || 0, maxZ2);
848	    }
849	
850	    // always set z and zlevel if label/labelLine exists
851	    if (label) {
852	        label.z = z;
853	        label.zlevel = zlevel;
854	        // lift z2 of text content
855	        // TODO if el.emphasis.z2 is spcefied, what about textContent.
856	        isFinite(maxZ2) && (label.z2 = maxZ2 + 2);
857	    }
858	    if (labelLine) {
859	        const textGuideLineConfig = el.textGuideLineConfig;
860	        labelLine.z = z;
861	        labelLine.zlevel = zlevel;
862	        isFinite(maxZ2)
863	            && (labelLine.z2 = maxZ2 + (textGuideLineConfig && textGuideLineConfig.showAbove ? 1 : -1));
864	    }
865	    return maxZ2;
866	}
